15	)
16	
17	type batchBuilder struct {
18		db           *sql.DB
19		args         []any
20		conditions   []string
21		batchSize    int
22		limitPerHost int
23	}
24	
25	func (s *Storage) NewBatchBuilder() *batchBuilder {
26		return &batchBuilder{
27			db: s.db,
28		}
29	}
30	
31	func (b *batchBuilder) WithBatchSize(batchSize int) *batchBuilder {
32		b.batchSize = batchSize
33		return b
34	}
35	
36	func (b *batchBuilder) WithUserID(userID int64) *batchBuilder {
37		b.conditions = append(b.conditions, "user_id = $"+strconv.Itoa(len(b.args)+1))
38		b.args = append(b.args, userID)
39		return b
40	}
41	
42	func (b *batchBuilder) WithCategoryID(categoryID int64) *batchBuilder {
43		b.conditions = append(b.conditions, "category_id = $"+strconv.Itoa(len(b.args)+1))
44		b.args = append(b.args, categoryID)
45		return b
46	}
47	
48	func (b *batchBuilder) WithErrorLimit(limit int) *batchBuilder {
49		if limit > 0 {
50			b.conditions = append(b.conditions, "parsing_error_count < $"+strconv.Itoa(len(b.args)+1))
51			b.args = append(b.args, limit)
52		}
53		return b
54	}
55	
56	func (b *batchBuilder) WithNextCheckExpired() *batchBuilder {
57		b.conditions = append(b.conditions, "next_check_at < now()")
58		return b
59	}
60	
61	func (b *batchBuilder) WithoutDisabledFeeds() *batchBuilder {
62		b.conditions = append(b.conditions, "disabled IS false")
63		return b
64	}
65	
66	func (b *batchBuilder) WithLimitPerHost(limit int) *batchBuilder {
67		if limit > 0 {
68			b.limitPerHost = limit
69		}
70		return b
71	}
72	
73	// FetchJobs retrieves a batch of jobs based on the conditions set in the builder.
74	// When limitPerHost is set, it limits the number of jobs per feed hostname to prevent overwhelming a single host.
75	func (b *batchBuilder) FetchJobs() (model.JobList, error) {
76		query := `SELECT id, user_id, feed_url FROM feeds`
77	
78		if len(b.conditions) > 0 {
79			query += " WHERE " + strings.Join(b.conditions, " AND ")
80		}
81	
82		query += " ORDER BY next_check_at ASC"
83	
84		if b.batchSize > 0 {
85			query += " LIMIT " + strconv.Itoa(b.batchSize)
86		}
87	
88		rows, err := b.db.Query(query, b.args...)
89		if err != nil {
90			return nil, fmt.Errorf(`store: unable to fetch batch of jobs: %v`, err)
91		}
92		defer rows.Close()
93	
94		jobs := make(model.JobList, 0, b.batchSize)
95		hosts := make(map[string]int)
96		nbRows := 0
97		nbSkippedFeeds := 0
98	
99		for rows.Next() {
100			var job model.Job
101			if err := rows.Scan(&job.FeedID, &job.UserID, &job.FeedURL); err != nil {
102				return nil, fmt.Errorf(`store: unable to fetch job record: %v`, err)
103			}
104	
105			nbRows++
106	
107			if b.limitPerHost > 0 {
108				feedHostname := urllib.Domain(job.FeedURL)
109				if hosts[feedHostname] >= b.limitPerHost {
110					slog.Debug("Feed host limit reached for this batch",
111						slog.String("feed_url", job.FeedURL),
112						slog.String("feed_hostname", feedHostname),
113						slog.Int("limit_per_host", b.limitPerHost),
114						slog.Int("current", hosts[feedHostname]),
115					)
116					nbSkippedFeeds++
117					continue
118				}
119				hosts[feedHostname]++
120			}
121	
122			jobs = append(jobs, job)
123		}
124	
125		if err := rows.Err(); err != nil {
126			return nil, fmt.Errorf(`store: error iterating on job records: %v`, err)
127		}
128	
129		slog.Info("Created a batch of feeds",
130			slog.Int("batch_size", b.batchSize),
131			slog.Int("rows_count", nbRows),
132			slog.Int("skipped_feeds_count", nbSkippedFeeds),
133			slog.Int("jobs_count", len(jobs)),
134		)
135	
136		return jobs, nil
137	}
