func (f *Feed) ScheduleNextCheck(weeklyCount int, refreshDelay time.Duration) time.Duration {
	// A per-feed refresh interval overrides the global scheduler configuration.
	if f.RefreshInterval > 0 {
		interval := time.Duration(f.RefreshInterval) * time.Minute

		// Still honour the delay requested by the server (Retry-After, TTL, etc.),
		// bounded by the scheduler max interval unless the feed interval is larger.
		if refreshDelay > interval {
			maxInterval := config.Opts.SchedulerRoundRobinMaxInterval()
			if config.Opts.PollingScheduler() == SchedulerEntryFrequency {
				maxInterval = config.Opts.SchedulerEntryFrequencyMaxInterval()
			}
			interval = max(interval, min(refreshDelay, maxInterval))
		}

		f.NextCheckAt = time.Now().Add(interval)
		return interval
	}

