// SetRefreshInterval changes the per-feed refresh interval (in minutes) and
// brings the next check forward when the new interval requires it.
func (f *Feed) SetRefreshInterval(minutes int) {
	if minutes < 0 {
		minutes = 0
	}
	if minutes == f.RefreshInterval {
		return
	}
	f.RefreshInterval = minutes
	if minutes > 0 {
		nextCheck := time.Now().Add(time.Duration(minutes) * time.Minute)
		if f.NextCheckAt.After(nextCheck) {
			f.NextCheckAt = nextCheck
		}
	}
}

